// ---------------------------------------------------------------------------
// config - the only node you edit.
//
// Nothing in this workflow reads $env, so it behaves identically on self-hosted
// n8n and on n8n Cloud, needs no N8N_BLOCK_ENV_ACCESS_IN_NODE, and a threshold
// change costs a save rather than a host restart.
//
// Leave a key blank and that step is SKIPPED, not failed:
//   APOLLO_API_KEY       blank -> the waterfall starts at RocketReach
//   ROCKETREACH_API_KEY  blank -> the waterfall starts at the pattern guess
//   VERIFIER_API_KEY     blank -> nothing is verified, so pattern guesses are
//                                 discarded and provider hits come back as
//                                 email_status "unknown" rather than "valid"
//
// All three blank is a valid dry run: import, hit Execute, watch the shape of
// the response without spending a credit anywhere.
// ---------------------------------------------------------------------------

const APOLLO_API_KEY = '';
const ROCKETREACH_API_KEY = '';
const VERIFIER_API_KEY = '';

// neverbounce | zerobounce | millionverifier
const VERIFIER = 'neverbounce';

// Some clients would rather have a blank than an attempted guess. Off means the
// waterfall stops after RocketReach.
const PATTERN_GUESS_ENABLED = true;

// Handed back to the caller as recommended_action, so the thresholds agreed on
// the call are the thresholds the data carries.
const MIN_CONFIDENCE_TO_SEND = 70;
const MIN_CONFIDENCE_TO_REVIEW = 40;

// ---------------------------------------------------------------------------
// derived - nothing below here needs editing
// ---------------------------------------------------------------------------

// All three verifiers take the key and the address as query parameters, so the
// provider switch is one URL rather than a rewired node. The address is
// appended, url-encoded, by the verifier node.
const VERIFIER_URLS = {
  neverbounce: 'https://api.neverbounce.com/v4/single/check?key=' +
    encodeURIComponent(VERIFIER_API_KEY) + '&email=',
  zerobounce: 'https://api.zerobounce.net/v2/validate?api_key=' +
    encodeURIComponent(VERIFIER_API_KEY) + '&email=',
  millionverifier: 'https://api.millionverifier.com/api/v3/?api=' +
    encodeURIComponent(VERIFIER_API_KEY) + '&email='
};

const apolloKey = String(APOLLO_API_KEY || '').trim();
const rocketreachKey = String(ROCKETREACH_API_KEY || '').trim();
const verifierKey = String(VERIFIER_API_KEY || '').trim();
const verifier = String(VERIFIER || 'neverbounce').trim().toLowerCase();

if (!VERIFIER_URLS[verifier]) {
  throw new Error('config: VERIFIER must be one of ' +
    Object.keys(VERIFIER_URLS).join(', ') + ' - got "' + VERIFIER + '"');
}

return [{
  json: {
    apollo_api_key: apolloKey,
    rocketreach_api_key: rocketreachKey,
    verifier_api_key: verifierKey,
    verifier: verifier,
    verifier_url: VERIFIER_URLS[verifier],

    apollo_enabled: apolloKey !== '',
    rocketreach_enabled: rocketreachKey !== '',
    verifier_enabled: verifierKey !== '',
    pattern_guess_enabled: PATTERN_GUESS_ENABLED === true,

    min_confidence_to_send: MIN_CONFIDENCE_TO_SEND,
    min_confidence_to_review: MIN_CONFIDENCE_TO_REVIEW
  }
}];

// One input shape for the whole waterfall, whatever the caller sent.
// Reads the trigger by name rather than $input, because the node in front of
// this one is config and carries settings, not the request.
const cfg = $('config').first().json;
const raw = $('Webhook - enrich request').first().json || {};
const b = raw.body || raw;

const slug = (s) => String(s || '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '');

let domain = String(b.domain || b.company_domain || '').toLowerCase().trim();
domain = domain.split('//').pop().split('/')[0].split('?')[0];
if (domain.startsWith('www.')) domain = domain.slice(4);

const first = String(b.first_name || '').trim();
const last = String(b.last_name || '').trim();

// lead_id is the dedupe key everywhere downstream (see _shared/conventions.md).
// The caller owns it; we only mint one when it is missing, and we say so, so a
// caller that thought it was sending one can see that it did not arrive.
const suppliedId = String(b.lead_id || '').trim();
const leadId = suppliedId || (slug(domain) + '-' + slug(first + ' ' + last)).replace(/^-|-$/g, '');

const skipped = [];
if (!cfg.apollo_enabled) skipped.push('apollo');
if (!cfg.rocketreach_enabled) skipped.push('rocketreach');
if (!cfg.pattern_guess_enabled) skipped.push('pattern');
if (!cfg.verifier_enabled) skipped.push('verifier');

return [{
  json: {
    lead_id: leadId,
    lead_id_generated: suppliedId === '',
    first_name: first,
    last_name: last,
    full_name: (first + ' ' + last).trim(),
    title: String(b.title || '').trim(),
    company: String(b.company || '').trim(),
    domain: domain,
    linkedin_url: String(b.linkedin_url || '').trim(),
    callback_url: String(b.callback_url || '').trim(),
    email: '',
    email_source: '',
    email_status: 'unknown',
    confidence: 0,
    tried: [],
    providers_skipped: skipped
  }
}];

// One lead per request - Clay calls this once per row - so there is exactly one
// item. Read Apollo without letting a locked placeholder through as if it were
// a real address: email_not_unlocked@domain.com is Apollo telling us to pay,
// not a contact.
const lead = Object.assign({}, $('normalise request').first().json);
const res = $input.first().json || {};
const person = res.person || {};
const email = String(person.email || '');
const usable = email.includes('@') && !email.includes('email_not_unlocked');

lead.tried = (lead.tried || []).concat(['apollo']);
if (usable) {
  lead.email = email.toLowerCase();
  lead.email_source = 'apollo';
}
if (!lead.title && person.title) lead.title = person.title;
if (!lead.company && person.organization && person.organization.name) {
  lead.company = person.organization.name;
}

return [{ json: lead }];

// Prefer a professional address over a personal one, and skip the grades
// RocketReach itself has no confidence in - a graded-F address is not a
// finding. Base comes from the merge rather than from the Apollo reader,
// because the Apollo reader does not run when APOLLO_API_KEY is blank.
const lead = Object.assign({}, $('waterfall after Apollo').first().json);
const res = $input.first().json || {};
const emails = Array.isArray(res.emails) ? res.emails : [];

const professional = emails.find((e) => e.email && e.type === 'professional' && e.grade !== 'F');
const fallback = emails.find((e) => e.email && e.grade !== 'F');
const picked = professional || fallback;

lead.tried = (lead.tried || []).concat(['rocketreach']);
if (picked) {
  lead.email = String(picked.email).toLowerCase();
  lead.email_source = 'rocketreach';
}
if (!lead.title && res.current_title) lead.title = res.current_title;

return [{ json: lead }];

// Step 3, and the honest one: a pattern guess is a hypothesis, not a contact.
// It only survives if the verifier independently says the mailbox exists, which
// is enforced in "score confidence" - so with no verifier key configured, a
// guess can never leave this workflow.
const cfg = $('config').first().json;

return $input.all().map((item) => {
  const lead = Object.assign({}, item.json);

  if (!cfg.pattern_guess_enabled) return { json: lead };

  const f = String(lead.first_name || '').toLowerCase().replace(/[^a-z]/g, '');
  const l = String(lead.last_name || '').toLowerCase().replace(/[^a-z]/g, '');
  const d = lead.domain;

  lead.tried = (lead.tried || []).concat(['pattern']);

  if (f && l && d) {
    lead.email = f + '.' + l + '@' + d;
    lead.email_source = 'pattern';
  }

  return { json: lead };
});

// Normalise three vendors' vocabularies into four words, so "score confidence"
// never learns which verifier the client bought.
//
// Anything unrecognised - including a vendor error payload or an exhausted
// credit balance - lands on "unknown", never on "valid". The failure mode of a
// verifier outage has to be a lead nobody sends to yet, not a lead everybody
// sends to.
const cfg = $('config').first().json;
const res = $input.first().json || {};

const raw = String(cfg.verifier === 'zerobounce' ? (res.status || '') : (res.result || ''))
  .trim().toLowerCase();

const MAP = {
  valid: 'valid',
  ok: 'valid',
  invalid: 'invalid',
  disposable: 'invalid',
  spamtrap: 'invalid',
  abuse: 'invalid',
  do_not_mail: 'invalid',
  catchall: 'risky',
  'catch-all': 'risky',
  catch_all: 'risky',
  accept_all: 'risky',
  unknown: 'unknown'
};

return [{
  json: {
    verdict: MAP[raw] || 'unknown',
    verifier: cfg.verifier,
    verifier_raw: raw || 'no-response'
  }
}];

// Confidence combines where the address came from with what the verifier said.
// A pattern guess the verifier will not confirm is discarded, not downgraded -
// handing a client a plausible-looking guess is how a sending domain gets
// burned three weeks later, for reasons nobody connects back to enrichment.
const cfg = $('config').first().json;
const lead = Object.assign({}, $('collect candidates').first().json);
const inp = $input.first().json || {};

// Three ways in: the verifier reader (carries a verdict), the "verifier not
// configured" skip, and the "no address to check" skip. The last two pass the
// lead straight through, so the absence of a verdict is the signal.
const verdict = typeof inp.verdict === 'string'
  ? inp.verdict
  : (lead.email ? 'unverified' : 'none');

const SOURCE_WEIGHT = { apollo: 70, rocketreach: 65, pattern: 25 };
const VERDICT_WEIGHT = { valid: 30, risky: 5, unknown: 0, unverified: 0, none: 0, invalid: -100 };

let confidence = (SOURCE_WEIGHT[lead.email_source] || 0) + (VERDICT_WEIGHT[verdict] || 0);

const guessUnconfirmed = lead.email_source === 'pattern' && verdict !== 'valid';
if (verdict === 'invalid' || guessUnconfirmed) {
  lead.email = '';
  lead.email_source = '';
  confidence = 0;
}
if (confidence < 0) confidence = 0;
if (confidence > 100) confidence = 100;

// A blank field is a fact the client can act on. A guess is a liability with
// good manners.
const statusOf = { valid: 'valid', risky: 'risky', invalid: 'invalid' };
lead.email_status = lead.email ? (statusOf[verdict] || 'unknown') : 'unknown';
lead.confidence = confidence;
lead.stage = lead.email ? 'enriched' : 'new';

let action = confidence >= cfg.min_confidence_to_send
  ? 'send'
  : (confidence >= cfg.min_confidence_to_review ? 'review' : 'do_not_send');

// A catch-all domain accepts every address, so "it did not bounce" proves
// nothing about the mailbox. It scores well and still belongs in its own
// segment, sent last and watched on its own - never mixed into the main send.
if (lead.email_status === 'risky' && action === 'send') action = 'review';

lead.recommended_action = action;

lead.verification = {
  verifier: verdict === 'unverified' || verdict === 'none' ? 'none' : (inp.verifier || cfg.verifier),
  verdict: verdict,
  raw: inp.verifier_raw || null
};

lead.enriched_at = new Date().toISOString();
delete lead.callback_url;

return [{ json: lead }];
